#{{ID}} .btb-fw-container {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 1920px;
    height: var(--v-height, 55px);
    background: {{PRIMARY_COLOR}};
    display: flex;
    align-items: center;
    overflow: hidden;
    opacity: 0;
    transform: translateY(55px);
    box-sizing: border-box;
}
#{{ID}} .btb-fw-track-wrapper {
    position: relative;
    flex: 1;
    overflow: hidden;
    height: 100%;
    display: flex;
    align-items: center;
}
#{{ID}} .btb-fw-track {
    display: flex;
    align-items: center;
    white-space: nowrap;
    height: 100%;
    will-change: transform;
}
#{{ID}} .btb-fw-item {
    color: {{TITLE_COLOR}};
    font-family: 'Bahnschrift', '{{FONT_FAMILY}}', sans-serif;
    font-size: {{TITLE_SIZE}}px;
    font-weight: {{TITLE_WEIGHT}};
    text-transform: {{TITLE_TRANSFORM}};
    white-space: nowrap;
    padding: 0 28px;
    line-height: 1;
    display: inline-flex;
    align-items: center;
}
#{{ID}} .btb-fw-sep {
    display: inline-block;
    width: 6px;
    height: 6px;
    background: {{TITLE_COLOR}};
    border-radius: 50%;
    opacity: 0.5;
    flex-shrink: 0;
    margin: 0 4px;
}

codeBackup.js_template:
(() => {
    const root = document.getElementById('{{ID}}');
    const container = root.querySelector('.btb-fw-container');
    const track = root.querySelector('.btb-fw-track');
    const dataEl = root.querySelector('#f-news-list');
    if (!container || !track || !dataEl) return;

    const SPEED = parseFloat('{{TICKER_SPEED}}') || 120;

    let items = [];
    const b64 = dataEl.getAttribute('data-b64');
    if (b64) {
        try {
            items = JSON.parse(decodeURIComponent(escape(atob(b64 + '='.repeat((4 - b64.length % 4) % 4)))));
        } catch(e) { items = []; }
    }
    if (!items.length) items = [{ text: 'BRAK WIADOMOŚCI' }];
    const getText = (item) => (typeof item === 'object') ? (item.text || '') : String(item);

    function buildTrack() {
        track.innerHTML = '';
        // Powiel 3x aby scroll był bezproblemowy
        for (let r = 0; r < 3; r++) {
            items.forEach(item => {
                const span = document.createElement('span');
                span.className = 'btb-fw-item';
                span.innerHTML = getText(item);
                track.appendChild(span);
                const dot = document.createElement('span');
                dot.className = 'btb-fw-sep';
                track.appendChild(dot);
            });
        }
    }

    let animId = null;
    let running = false;
    let xPos = 0;
    let singleCycleWidth = 0;
    let lastTime = null;

    function measureCycle() {
        // Szerokość jednej pełnej kopii
        const total = track.scrollWidth;
        singleCycleWidth = total / 3;
    }

    function tick(timestamp) {
        if (!running) return;
        if (lastTime === null) lastTime = timestamp;
        const dt = (timestamp - lastTime) / 1000;
        lastTime = timestamp;
        xPos -= SPEED * dt;
        if (singleCycleWidth > 0 && Math.abs(xPos) >= singleCycleWidth) {
            xPos += singleCycleWidth;
        }
        track.style.transform = 'translateX(' + xPos + 'px)';
        animId = requestAnimationFrame(tick);
    }

    root.__slt_show = () => {
        buildTrack();
        requestAnimationFrame(() => {
            measureCycle();
            running = true;
            lastTime = null;
            animId = requestAnimationFrame(tick);
        });
        const tl = gsap.timeline();
        tl.to(container, { opacity: 1, y: 0, duration: 0.5, ease: 'power2.out' });
        return tl;
    };

    root.__slt_hide = () => {
        running = false;
        if (animId) cancelAnimationFrame(animId);
        const tl = gsap.timeline();
        tl.to(container, { opacity: 0, y: 55, duration: 0.35, ease: 'power2.in' });
        return tl;
    };
})();

